def cache_dir() -> Path:
    "litesearch's cache folder: `LITESEARCH_CACHE`, else `$XDG_CACHE_HOME/litesearch`, else `~/.cache/litesearch`."
    if (p := os.environ.get('LITESEARCH_CACHE')): return Path(p)
    return Path(os.environ.get('XDG_CACHE_HOME') or Path.home()/'.cache')/'litesearch'

def cpu_model() -> str:
    "The CPU's model name: `/proc/cpuinfo` on Linux, `sysctl` on macOS, else the machine type."
    try:
        if Path('/proc/cpuinfo').exists():
            for l in open('/proc/cpuinfo'):
                if l.startswith('model name'): return l.split(':', 1)[1].strip()
        if platform.system() == 'Darwin':
            return subprocess.run(['sysctl', '-n', 'machdep.cpu.brand_string'], capture_output=True, text=True).stdout.strip() or platform.machine()
    except Exception: pass
    return platform.machine()

@contextmanager
def _cache_lock(name):
    "Hold an exclusive lock on `cache_dir()/.<name>.lock` for the block; no lock when the folder cannot be written."
    try: d = cache_dir(); d.mkdir(parents=True, exist_ok=True); f = open(d/f'.{name}.lock', 'w')
    except OSError: yield; return
    with f: fcntl.flock(f, fcntl.LOCK_EX); yield

def _lib_file(p): return Path(p + {'Darwin': '.dylib', 'Windows': '.dll'}.get(platform.system(), '.so'))

_lib_path = None
def _lib(fresh=False):
    "Path of usearch's SQLite extension without suffix; `fresh` deletes the file so usearch downloads it again."
    global _lib_path
    if _lib_path and not fresh: return _lib_path
    from usearch import sqlite_path
    if fresh: _lib_file(sqlite_path()).unlink(missing_ok=True)
    usearch_fix(path=(p := sqlite_path()))
    _lib_path = p
    return p

def usearch_lib() -> str:
    "Path of usearch's SQLite extension without suffix, downloaded under a lock so no process loads a half-written file."
    if _lib_path: return _lib_path
    with _cache_lock('usearch'): return _lib()

