_PROBE = """import sys, numpy as np
from usearch.index import Index
i = Index(ndim=4, metric='cos', dtype='f32'); i.add(np.arange(2), np.eye(2, 4, dtype=np.float32))
assert int(i.search(np.eye(1, 4, dtype=np.float32)[0], count=1).keys[0]) == 0
print('index', flush=True)
if len(sys.argv) > 1:
    import apsw
    c = apsw.Connection(':memory:'); c.enableloadextension(True); c.loadextension(sys.argv[1])
    v = np.ones(4, np.float32).tobytes()
    assert c.execute('select distance_cosine_f32(?, ?)', (v, v)).fetchone()[0] < 1e-3
    print('sql', flush=True)"""

def _signame(n):
    try: return signal.Signals(n).name
    except ValueError: return f'signal {n}'

def _probe(lib=None) -> dict:
    "Run `_PROBE` in a fresh interpreter: which of `index` and `sql` passed, and `why` the rest did not."
    try: r = subprocess.run([sys.executable, '-c', _PROBE] + ([lib] if lib else []), capture_output=True, text=True, timeout=120)
    except (OSError, subprocess.TimeoutExpired) as e: return dict(index=False, sql=False, why=f'the probe did not finish ({e})')
    out = r.stdout.split()
    why = (f'the probe died of {_signame(-r.returncode)}' if r.returncode < 0 else
           f'the probe failed ({(r.stderr.strip().splitlines() or [f"exit {r.returncode}"])[-1]})' if r.returncode else '')
    return dict(index='index' in out, sql=bool(lib) and 'sql' in out, why=why)

def _key(lib):
    import usearch
    return f'{cpu_model()} | usearch {usearch.__version__} | {_lib_file(lib).stat().st_size} bytes'

def _decide() -> dict:
    "The probe's verdict for this machine, read from `usearch.json` or probed and written there."
    if getattr(sys, 'frozen', False): return dict(index=True, sql=True, why='')
    f = cache_dir()/'usearch.json'
    with _cache_lock('usearch'):
        try: lib = _lib()
        except Exception as e: return {**_probe(), 'why': f'the SQLite extension is unavailable ({e})'}
        try: seen = json.loads(f.read_text())
        except (OSError, ValueError): seen = {}
        if (k := _key(lib)) in seen: return seen[k]
        v = _probe(lib)
        if v['index'] and not v['sql']:
            try: lib = _lib(fresh=True); k = _key(lib); v = _probe(lib)
            except Exception as e: return {**v, 'why': f"{v['why']}; downloading it again failed ({e})"}
        seen[k] = v
        try: (t := f.with_name(f'.{f.name}.{os.getpid()}')).write_text(json.dumps(seen, indent=1)); os.replace(t, f)
        except OSError: pass
        return v

_verdict, _vlock = None, threading.Lock()
def usearch_ok(part:str='sql') -> bool:
    "Whether usearch's `part`, 'sql' (the SQLite extension) or 'index' (HNSW), is on: `LITESEARCH_USEARCH=0|1`, else the probe's verdict."
    global _verdict
    if (e := os.environ.get('LITESEARCH_USEARCH', '').strip()) in ('0', '1'): return e == '1'
    with _vlock:
        if _verdict is None:
            _verdict = _decide()
            if (off := [n for n, w in (('SQLite extension', 'sql'), ('HNSW index', 'index')) if not _verdict[w]]):
                warnings.warn(f"usearch's {' and '.join(off)} is off on {cpu_model()}: {_verdict['why'] or 'it failed its probe'}. "
                              f"litesearch searches those vectors exactly with numpy. Set LITESEARCH_USEARCH=1 to use usearch anyway, "
                              f"or delete {cache_dir()/'usearch.json'} to probe again.", stacklevel=2)
    return _verdict[part]
